<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&amp;display=swap');

        body {
            font-family: "Times New Roman", serif;
            line-height: 1.4;
            margin: 2cm auto;
            max-width: 180mm;
            background: #fff;
            color: #000;
            padding: 0 1cm;
        }

        .page {
            page-break-after: always;
            position: relative;
        }

        .column {
            display: flex;
            gap: 1cm;
        }

        .col {
            flex: 1;
        }

        h1 {
            font-size: 24pt;
            text-align: center;
            margin-bottom: 1.5em;
        }

        h2 {
            font-size: 18pt;
            margin-top: 1.5em;
            margin-bottom: 0.5em;
        }

        .italic {
            font-style: italic;
        }

        .placeholder {
            border: 1px dashed #999;
            background: #f9f9f9;
            padding: 10px;
            margin: 1em 0;
            text-align: center;
            font-style: italic;
            color: #666;
        }

        .signature {
            border-top: 1px solid #000;
            width: 60%;
            margin-top: 3em;
        }
    </style>
</head>
<body>

<!-- PAGE 1 -->
<div class="page">
    <h1>Sample Document</h1>

    <div class="column">
        <div class="col">
            <p><strong>Left Column</strong></p>
            <p>This is the left column text extracted verbatim from the image.</p>
            <p>This is the second paragraph in the left column.</p>
        </div>
        <div class="col">
            <p><strong>Right Column</strong></p>
            <p>This is the right column text extracted verbatim from the image.</p>
            <p>This is the second paragraph in the right column.</p>
        </div>
    </div>

    <div class="placeholder" style="width:100%; height:150px; margin-top:2em;">
        [Image: Centered photograph or diagram]
    </div>

    <p style="margin-top:3em;"><span class="italic">Italicized text example</span> – some text remains italic in the layout.</p>

    <div style="margin-top:3em;">
        <div style="width:50%; display:inline-block; vertical-align:top;">
            <p>Left-aligned label</p>
            <p style="border:1px solid #000; padding:5px;">[Checkbox / Signature placeholder]</p>
        </div>
        <div style="width:45%; display:inline-block; margin-left:5%; vertical-align:top;">
            <p>Right-aligned label</p>
            <p style="border:1px solid #000; padding:5px;">[Signature area]</p>
        </div>
    </div>
</div>

<!-- PAGE 2 -->
<div class="page">
    <h2>Second Page Heading</h2>

    <div class="column">
        <div class="col">
            <p>Left column on page two.</p>
            <p>More text continues here.</p>
        </div>
        <div class="col">
            <p>Right column on page two.</p>
            <p>Additional content here.</p>
        </div>
    </div>

    <div class="placeholder" style="width:70%; height:100px; margin:2em auto;">
        [Figure: Diagram located at center]
    </div>

    <div class="signature">
        Signature area
    </div>
</div>

</body>
</html>
```
